from author import *
c=C('体系结构与数据表示')
add(c,'课程知识地图',[('目标','能逐条读懂8086代码，追踪数据与执行方向'),('方法','先确定条件，再看寄存器、内存与标志的变化')],[P('欢迎来到一小时讲完汇编语言。这节课从寄存器和内存讲起，带你逐条读懂传送、运算、判断、循环和子程序。我们采用八零八六实模式，代码使用NASM的Intel写法。左侧显示源代码，下方列出完整运行后的检查结果，右侧展示当前这一步的数据变化。你可以边听边记下每次改动的位置，再与画面核对。十个章节各有一道练习，讲完题目留四秒思考，随后给出答案与计算过程。',1,['零基础，从读懂一条指令开始','8086实模式；NASM Intel语法'])],kind='overview')
L(c,'汇编、机器码与执行',('三种形式','需求：把3与5相加 → 汇编指令 → 机器码'),('阅读方向','Intel写法通常把目标写在左边，来源写在右边'),
'我们先完成一个很小的任务：计算三加五。先把三放进AX，再让AX加五，结果就保存在AX里。AX是处理器内部一个有名字的存储位置，后面会经常用到。汇编语言用MOV、ADD这样的名称表达动作，汇编器把这些文字翻译成机器码，处理器再执行机器码。把这个过程分成写代码、汇编、执行三步，就能看清我们写的文字怎样变成一次真实的数据变化。',
'现在先执行传送，把三写入AX，来源是指令里直接给出的数值。随后执行加法，从AX读出三，与五相加，再把八写回AX。沿着这个过程看，数据先被读取，接着参加计算，最后回到目标位置。Intel写法通常把目标放在左边、来源放在右边，所以ADD后面的AX就是这次写回的位置。读下一段代码时，也可以按读取、计算、写回这三个动作逐步追踪。',['汇编器翻译，处理器执行','先把AX当成有名字的存储位置'],['目标通常在左，来源在右','动画放慢展示指令的数据流'],code='mov ax, 3\nadd ax, 5',run='intro_add',output=['AX=0008h（十进制8）'],lines=[[1],[1]],visual=V('execution',trace='intro_add',windows=[[0,0],[0,2]],regs=['ax','ip']),anchors=[None,'现在先执行传送'],hints=[[],[('随后执行加法',[2])]])
L(c,'二进制、十六进制与位宽',('表示方式','1字节=8位；本课1字=16位；十六进制每位对应4个比特'),('同一位串','FFh按8位无符号解释为255，按8位补码解释为−1'),
'计算机用零和一保存数据。一个比特保存一个零或一，八个比特组成一个字节；八零八六中的一个字是十六位，也就是两个字节。为了让长位串更好读，我们把每四位二进制换成一位十六进制。八个一写成FF，后面的H表示十六进制。这样，一个字节通常用两位十六进制显示，一个字通常用四位显示，后面观察寄存器和内存就会方便很多。',
'现在对照这两种解释：八位全一按无符号数计算，是一百二十八加一百二十七，得到二百五十五；按补码计算，是负一百二十八加一百二十七，得到负一。位串保持相同，计算规则由数据的用途决定。八位无符号范围是零到二百五十五，八位有符号范围是负一百二十八到一百二十七。先写出位宽和解释方式，再进行大小比较、扩展和溢出判断，后面的选择就有了依据。',['位宽、数制与有无符号分开','本课的字是16位'],['同一位串可以有不同解释','比较与溢出要连同解释判断'],visual=V('representation'),anchors=[None,'现在对照这两种解释'])
L(c,'寄存器与高低字节',('重叠关系','AX由AH高8位和AL低8位共同组成'),('常见用途','BX常用于寻址，CX常用于计数；用途仍取决于指令约定'),
'先写AX为十六进制一二三四，把它分成左右两组看：高八位AH是一二，低八位AL是三四。AH与AL合起来组成完整的十六位AX，访问这三个名字，就是从不同范围观察同一份数据。AX、BX、CX、DX都有这样的高低字节划分。看见操作数AL，可以先在AX的低半部画个框，明确这一条指令将修改哪八个位，读执行结果时再把两部分合起来。',
'现在把AL单独改成五六，低半部更新，高半部AH继续保存一二，合起来AX就是一二五六。由此可以按范围检查每次写入：写AX会同时涉及高低两部分，写AH或AL只更新对应的八位。其他寄存器还有各自常见的用途，BX常参加寻址，CX常保存计数。遇到乘法、循环和字符串指令时，我们会把它们隐含使用的寄存器逐项标出来，读代码时就有了具体的查找位置。',['AX、AH、AL共享同一份位','先按16位拆成两个8位'],['写AL更新低8位，AH保持原值','隐含寄存器由指令规则决定'],code='mov ax, 1234h\nmov al, 56h',run='register_parts',output=['AX=1256h；AH=12h；AL=56h'],lines=[[1],[2]],visual=V('execution',trace='register_parts',windows=[[1,1],[1,2]],regs=['ax','ah','al']),anchors=[None,'现在把AL单独改成五六'])
L(c,'内存编址与小端存放',('内存单位','每个地址对应1字节；相邻地址相差1'),('小端顺序','字1234h写到0200h：低地址34h，高地址12h'),
'把内存画成一排编号的小格，每个地址对应一个字节。寄存器通过名字访问，内存通过地址访问。要保存AX这样的十六位值，需要连续两个格子。八零八六采用小端顺序：低八位放在较低地址，高八位放在下一个地址。这里数据段已经设置好，我们先关注段内偏移。画内存时，按地址从小到大排格子，再把一个字拆成高低字节，存放过程就清楚了。',
'现在把一二三四这个字写到偏移零二零零。先拆成高字节一二、低字节三四，再把三四填进零二零零，把一二填进零二零一。再按字读回时，处理器把这两个字节组合成一二三四，交给BX。一次字读取使用两个连续字节，两个地址相差一。以后读数组和栈里的字，也可以沿用这个方法：先确定起始地址，找到两个字节，最后按小端顺序拼出完整数值。',['一个地址对应一个字节','字需要连续两个字节'],['低字节放低地址','按字节排列，高低位顺序保留'],code='mov ax, 1234h\nmov [0200h], ax\nmov bx, [0200h]',run='little_endian',output=['[0200h]=34h，[0201h]=12h；BX=1234h'],lines=[[1],[2]],visual=V('execution',trace='little_endian',windows=[[1,1],[1,3]],regs=['ax','bx'],memory=[0x200,0x201]),anchors=[None,'现在把一二三四这个字写到偏移零二零零'],hints=[[],[('再按字读回时',[3])]])
L(c,'段地址、偏移与执行位置',('实模式地址','物理地址=段值×16+偏移；本课例子放在1MB范围内'),('两组关系','CS:IP指向指令；普通数据常用DS；栈主要使用SS:SP'),
'八零八六实模式用段值和偏移共同表示位置。段值乘十六得到段基址，再加偏移，得到物理地址。比如段值一二三四H、偏移零零一零H，段基址是一二三四零H，相加得到一二三五零H。十六进制乘十六，可以在末尾补一个零。段值一二三五H、偏移零，也会得到同一个物理地址。用两组数字分步计算，就能看清段、偏移与实际内存格之间的关系。',
'现在把段基址与偏移分别放到图中，再做一次相加。执行指令时，CS与IP组合给出取指位置；访问普通数据时，常使用DS配合有效偏移；访问栈时，主要使用SS与SP。它们分别服务于代码、数据和栈。后面分析一条内存指令，我们先确定使用哪个段，再计算偏移，最后合成访问位置。这节课的地址例子都放在八零八六实模式中，先把这套规则练熟。',['实模式段基址是段值乘16','不同段偏移可以指向同一地址'],['取指、普通数据与栈分开看','地址例子放在1MB范围内'],visual=V('segment'),anchors=[None,'现在把段基址与偏移分别放到图中'])
Q(c,'寄存器与字节顺序',('操作','AX先为1234h，再执行mov al, 0ABh'),('问题','AX变成什么；按字写入0200h后两个字节如何排列'),
'AX最初是十六进制一二三四，现在执行一条MOV，把AL写成AB。请写出新的AX，再把这个字保存到偏移零二零零，写出零二零零与零二零一里的两个字节。可以先在AX上划分高低八位，再画两个带地址的内存格，把计算分成两步完成。接下来留四秒思考。',
'AH保存一二，AL更新为AB，合起来AX就是一二AB。按小端写入内存，低字节AB放在零二零零，高字节一二放在零二零一。检查时先确认寄存器的修改范围，再确认两个字节的存放顺序。把这两张小图连起来，就能追踪一个十六位值从寄存器到内存的完整过程。',('寄存器','AX=12ABh；AH=12h，AL=ABh'),('内存','[0200h]=ABh；[0201h]=12h'))

c=C('数据传送与寻址')
L(c,'传送指令与操作数',('基本形式','mov 目标, 来源；目标接收副本，来源保持原值'),('合法范围','两侧位宽匹配；内存间传送先经寄存器中转'),
'把七放进AX，再把AX复制到BX，执行以后两个寄存器都保存七。MOV复制的是来源里的位，目标接收这份副本，来源继续保存原值。直接写在指令里的七叫立即数，AX与BX则是寄存器操作数。还可以把内存位置作为来源或目标。读MOV时，先指出来源是哪一类，再看目标的宽度和位置，就能说清这次复制具体改变了哪里。',
'现在从AX复制到BX，BX取得七；再把AX单独改成九，AX成为九，BX继续保存七。这说明两个位置各自保存了一份数据。写指令时，让两侧宽度相配：十六位AX可以复制到十六位BX，八位AL可以复制到八位BL。从一个内存位置复制到另一个位置时，可以先读入寄存器，再写到目标内存。把复杂传送拆成明确的读取和写入，数据经过的路线也更容易检查。',['MOV复制数据，来源保持原值','立即数、寄存器、内存分开读'],['副本独立保存，后续改动分别进行','位宽与操作数组合都要合法'],code='mov ax, 7\nmov bx, ax\nmov ax, 9',run='move_copy',output=['AX=0009h；BX=0007h'],lines=[[1],[2]],visual=V('execution',trace='move_copy',windows=[[1,1],[1,3]],regs=['ax','bx']),anchors=[None,'现在从AX复制到BX'],hints=[[],[('再把AX单独改成九',[3])]])
L(c,'方括号与内存读写',('有无方括号','mov bx,0200h得到数值；mov bx,[0200h]读取该位置的字'),('给定条件','DS已设置；0200h起始字节为34h、12h'),
'比较两个很接近的写法：MOV后面直接写零二零零，是把这个数值送入寄存器；把它放进方括号，则按地址去内存取内容。这里零二零零与零二零一保存三四、一二，因此读一个字得到一二三四。先把地址值写在箭头起点，再把内存内容写在格子里面，就能在同一张图上区分地址与数据。方括号提示这次操作涉及地址表达式，具体动作再结合指令名称读取。',
'现在先取得地址数值，把零二零零保存到BX，再按这个地址读取内容，让AX取得一二三四。读取后，原来的两个字节继续保存在内存里。反过来，把AX写到方括号表示的位置，就是将这份数据存到目标地址。本例写入零二零二与零二零三，低字节三四在前，高字节一二在后。BX提供偏移，DS提供段基址，两者一起确定普通这类访问的位置。',['方括号决定是否取内存内容','先确认DS和给定初始字节'],['读取保留原字节，写入更新内容','地址值与地址处的数据分开'],code='mov bx, 0200h\nmov ax, [bx]\nmov [0202h], ax',run='memory_rw',output=['AX=1234h；[0202h]起的字=1234h'],lines=[[1],[1]],visual=V('execution',trace='memory_rw',windows=[[0,0],[0,3]],regs=['bx','ax'],memory=[0x200,0x201,0x202,0x203]),anchors=[None,'现在先取得地址数值'],hints=[[],[('再按这个地址读取内容',[2]),('反过来，把AX写到方括号表示的位置',[3])]])
L(c,'有效地址与LEA',('有效地址','先计算有效偏移，再进行对应访问'),('LEA作用','lea dx,[bx+si+2]将有效偏移写入DX'),
'数组访问常需要把起点、当前偏移与一个固定距离相加。比如BX是零二零零，SI是四，再加二，得到有效偏移零二零六。LEA可以把这种地址计算结果放到寄存器，所以DX可以接收零二零六这个偏移。把LEA理解为地址计算，会更容易看懂含有多个寄存器的表达式。写题时先把各项数值代进去，算出偏移，再决定下一步是保存这个地址，还是用它读取数据。',
'现在分别计算地址和读取内容：LEA将零二零六写入DX，后面的MOV才把这个位置的字读入AX。这里零二零六与下一字节预先保存七八、五六，组合成五六七八，因此AX取得这个值。纸上可以分两栏记录，左栏写有效地址，右栏写地址处的数据。遇到更长的表达式，继续按先算地址、再进行相应访问的顺序处理，每一步都有一个可以核对的结果。',['有效地址先算偏移','LEA计算并保存有效偏移'],['LEA结果是段内有效偏移','地址与内容分别记录'],code='mov bx, 0200h\nmov si, 4\nlea dx, [bx+si+2]\nmov ax, [bx+si+2]',run='lea_address',output=['DX=0206h；AX=5678h'],lines=[[1,2],[3]],visual=V('execution',trace='lea_address',windows=[[2,2],[2,4]],regs=['bx','si','dx','ax'],memory=[0x206,0x207]),anchors=[None,'现在分别计算地址和读取内容'],hints=[[],[('后面的MOV才把这个位置的字读入AX',[4])]])
L(c,'8086的寻址组合与默认段',('允许的基础组合','BX或BP可与SI或DI组合，并加位移'),('默认段','含BP的普通寻址默认SS；常见BX、SI、DI寻址默认DS'),
'八零八六的十六位寻址有一组固定搭配。常见单寄存器形式使用BX、BP、SI或DI；两寄存器形式可以让BX或BP分别搭配SI或DI，再加位移。比如BX加SI加二，就属于这样一组。看到地址表达式，先从表里找到它的组合，再代入数值。把这些合法形式按基址、变址和位移整理，比逐个背很多看起来相似的例子更容易记住。',
'现在对照同一个偏移，分别给它配上DS与SS。普通BX、SI、DI寻址常默认使用DS，包含BP的普通寻址默认使用SS。假设DS是一千H、SS是两千H，偏移都是零二零零，它们就分别访问一零二零零H与二零二零零H。指定其他段时，可以使用段超越前缀。分析地址题时，把默认段也写到表达式旁边，随后按段基址加偏移完成计算。',['16位寻址有固定组合限制','按8086的合法寻址组合选择寄存器'],['含BP的普通寻址默认SS','段值与偏移共同确定物理位置'],visual=V('address_modes'),anchors=[None,'现在对照同一个偏移'])
L(c,'数据声明、常量与大小说明',('NASM声明','db定义字节；dw定义字；equ定义汇编期常量'),('明确宽度','mov byte [0200h],1；立即数与内存组合需说明大小'),
'程序里的数据要按布局放进文件。DB按字节安排给出的值，DW按字安排十六位值，EQU则给汇编时能确定的常量起名字。比如三个字节可以顺序声明为三、五、七，一个十六位数可以用DW安排。数据标签标记这段内容的位置，后面的指令再通过标签求地址或访问内容。把声明看作准备数据，把MOV、ADD看作运行时的动作，文件组织和执行过程就能分开理解。',
'向内存写入常数时，我们明确指定访问范围。现在分别标出BYTE和WORD的范围：BYTE写一个字节，WORD写连续两个字节。假设原来是CD、AB，写一个字节的一，得到零一、AB；写一个字的一，则得到零一、零零。若另一侧是AX，十六位寄存器通常已经给出宽度。MASM教材中的BYTE PTR，对应这里NASM的BYTE；对照汇编器的写法，就能把同一个操作表达清楚。',['声明用于安排文件和汇编期信息','标签表示位置，访问宽度由指令指定'],['内存加立即数要明确大小','按NASM与MASM的语法分别书写'],visual=V('data_sizes'),anchors=[None,'现在分别标出BYTE和WORD的范围'])
Q(c,'地址与内容判断',('给定','DS正确；0200h、0201h分别是78h、56h'),('两条指令','mov bx,0200h；mov ax,[bx]'),
'数据段已经设置好，偏移零二零零与零二零一分别保存七八、五六。程序先把零二零零放入BX，再按BX指向的位置读取一个字到AX。请分别写出BX与AX的值。可以先标出BX里的地址，再用两个内存格拼出读到的数据，接下来留四秒思考。',
'BX保存偏移零二零零，AX读取低字节七八和高字节五六，组合成五六七八。读取完成后，BX继续提供原来的地址，两个内存格也保留原内容。这个过程里，BX负责定位，AX负责接收数据。把这两种角色分别标出来，再结合小端顺序，就能逐项核对答案。',('寄存器','BX=0200h；AX=5678h'),('保持项','原字节保留；BX保持原值'))
